+}
+
+func (f *fakeRefreshableCredential) ForceRefresh(_ context.Context, staleToken string) (string, error) {
+	f.forceCalls++
+	f.forcedStale = staleToken
+	f.token = f.forcedToken
+	return f.token, nil
+}
